style.css:
@-moz-document domain("jut.su") {
body {
        background: url("https://i.postimg.cc/QHVTGSgf/milk-outside-a-bag-of-milk-milk-chan.png") no-repeat center center fixed !important;
        background-size: cover !important;
        color: rgb(67, 39, 54) !important;
        font-family: "Segoe UI", "Roboto", sans-serif !important;
    }

    *, *:before, *:after {
        color: rgb(67, 39, 54) !important;
        background: transparent !important;
        background-color: transparent !important;
        border-color: rgb(67, 39, 54) !important;
    }

    a {
        color: rgb(67, 39, 54) !important;
    }

    button, input[type="submit"], .button {
        background-color: rgb(67, 39, 54) !important;
        color: #fff !important;
        border: none !important;
        border-radius: 5px !important;
        padding: 8px 16px !important;
        transition: background-color 0.3s ease !important;
    }

    button:hover, input[type="submit"]:hover, .button:hover {
        background-color: rgba(67, 39, 54, 0.8) !important;
    }
}
